import 'dart:math' as math;
import 'dart:io';
import 'package:flutter/material.dart';
import '../models/for_you_mix.dart';
import '../models/track_item.dart';
import '../services/playback_controller.dart';
import '../services/for_you_service.dart';
import '../theme/liquid_glass.dart';
import '../theme/typography.dart';
import '../widgets/autogenerated_mix_cover.dart';

/// AutogenMixStage: Dedicated Album View for Autogenerated Algorithmic Mixes.
/// Features SVG procedural vector art with dynamic breathing ambient effects,
/// Google M3 split pill button, rich algorithmic selection rationale, and full tracklist.
class AutogenMixStage extends StatefulWidget {
  final ForYouMix mix;
  final VoidCallback? onOpenNowPlaying;
  final ForYouArtStyle? styleOverride;

  const AutogenMixStage({
    super.key,
    required this.mix,
    this.onOpenNowPlaying,
    this.styleOverride,
  });

  @override
  State<AutogenMixStage> createState() => _AutogenMixStageState();
}

class _AutogenMixStageState extends State<AutogenMixStage>
    with SingleTickerProviderStateMixin {
  late final AnimationController _pulseController;
  late final Animation<double> _scaleAnimation;
  late final Animation<double> _glowAnimation;

  @override
  void initState() {
    super.initState();
    _pulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 3600),
    )..repeat(reverse: true);

    _scaleAnimation = Tween<double>(begin: 1.0, end: 1.045).animate(
      CurvedAnimation(parent: _pulseController, curve: Curves.easeInOutSine),
    );

    _glowAnimation = Tween<double>(begin: 0.30, end: 0.65).animate(
      CurvedAnimation(parent: _pulseController, curve: Curves.easeInOutSine),
    );
  }

  @override
  void dispose() {
    _pulseController.dispose();
    super.dispose();
  }

  String _formatDuration(Duration d) {
    final m = d.inMinutes;
    final s = d.inSeconds % 60;
    return '$m:${s.toString().padLeft(2, '0')}';
  }

  String _formatTotalRuntime(List<TrackItem> tracks) {
    final totalSeconds = tracks.fold<int>(0, (sum, t) => sum + t.duration.inSeconds);
    final m = totalSeconds ~/ 60;
    final s = totalSeconds % 60;
    return '${m}m ${s}s';
  }

  /// Synthesizes transparent, zero-hardcoded algorithmic rationale directly from track metadata
  String _synthesizeMixRationale(ForYouMix mix) {
    final tracks = mix.tracks;
    if (tracks.isEmpty) {
      return 'Generated based on your recent listening affinity and acoustic library transitions.';
    }

    final bpms = tracks.where((t) => t.hasBpm).map((t) => t.bpm).toList();
    final bpmRange = bpms.isNotEmpty
        ? 'spanning ${(bpms.reduce(math.min)).toStringAsFixed(1)} to ${(bpms.reduce(math.max)).toStringAsFixed(1)} BPM'
        : 'at steady dynamic tempo';

    final artists = tracks.map((t) => t.artist).where((a) => a.isNotEmpty).toSet().take(3).join(', ');
    final artistStr = artists.isNotEmpty ? 'featuring $artists' : '';

    switch (mix.id) {
      case 'mix_quick_picks':
        return 'Curated from your active library rotation and harmonic transition affinity $artistStr. '
            'Attune matched Camelot wheel harmonic keys to formulate a smooth, uninterrupted musical progression $bpmRange.';
      case 'mix_energy':
        return 'Selected for high-tempo drive and workout intensity $artistStr. '
            'Every track carries an elevated Aggression Index (A >= 0.60) $bpmRange, '
            'ideal for rapid DJ bass swaps and high-energy beat transitions.';
      case 'mix_chill':
        return 'Crafted for focused work, relaxed downtime, and late-night listening $artistStr. '
            'Focuses on gentle melodic phrase resolution, warm acoustic spectrums, and low harmonic dissonance $bpmRange.';
      case 'mix_bpm_sync':
        return 'Engineered for continuous rhythm lock $artistStr. '
            'Matches tracks strictly within a tight tempo window $bpmRange '
            'to ensure seamless DJ beat-matching and synchronized phrase handoffs.';
      case 'mix_rediscover':
        return 'Surfaces high-fidelity gems in your collection that haven\'t been queued recently $artistStr. '
            'Re-introduces diverse genres and forgotten favorites into your listening rotation $bpmRange.';
      default:
        return 'Algorithmic mix generated from ${tracks.length} tracks $artistStr $bpmRange. '
            'Crafted for dynamic DJ-grade crossfades and consistent vibe flow.';
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colorScheme = theme.colorScheme;
    final mix = widget.mix;

    return ListenableBuilder(
      listenable: PlaybackController.instance,
      builder: (context, _) {
        final controller = PlaybackController.instance;
        final totalRuntime = _formatTotalRuntime(mix.tracks);
        final bpms = mix.tracks.where((t) => t.hasBpm).map((t) => t.bpm).toList();
        final bpmSpan = bpms.isNotEmpty
            ? '${bpms.reduce(math.min).toStringAsFixed(0)}–${bpms.reduce(math.max).toStringAsFixed(0)} BPM'
            : 'Dynamic BPM';
        final losslessCount = mix.tracks.where((t) => t.isLossless).length;
        final losslessRatio = mix.tracks.isNotEmpty
            ? '${((losslessCount / mix.tracks.length) * 100).toInt()}% Lossless'
            : 'Lossless';

        return Scaffold(
          backgroundColor: const Color(0xFF0D1117),
          body: SafeArea(
            bottom: false,
            child: ListView(
              physics: const BouncingScrollPhysics(),
              padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 16.0),
              children: [
                // Top Navigation Bar
                Row(
                  children: [
                    IconButton.filledTonal(
                      icon: const Icon(Icons.arrow_back_rounded),
                      tooltip: 'Back',
                      onPressed: () => Navigator.of(context).pop(),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'ALGORITHMIC MIX ALBUM',
                            style: AttuneTypography.soraBadge(
                              fontSize: 10,
                              color: mix.primaryColor,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                          Text(
                            mix.title,
                            style: AttuneTypography.soraHeading(
                              fontSize: 18,
                              color: Colors.white,
                              fontWeight: FontWeight.w700,
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ],
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 24),

                // Hero Artwork with dynamic breathing pulse & ambient glow
                Center(
                  child: AnimatedBuilder(
                    animation: _pulseController,
                    builder: (context, child) {
                      return Transform.scale(
                        scale: _scaleAnimation.value,
                        child: Container(
                          decoration: BoxDecoration(
                            borderRadius: BorderRadius.circular(32),
                            boxShadow: [
                              BoxShadow(
                                color: mix.primaryColor.withValues(alpha: _glowAnimation.value),
                                blurRadius: 36 * _scaleAnimation.value,
                                spreadRadius: 3 * _scaleAnimation.value,
                                offset: const Offset(0, 10),
                              ),
                              BoxShadow(
                                color: mix.secondaryColor.withValues(alpha: _glowAnimation.value * 0.7),
                                blurRadius: 24,
                                offset: const Offset(0, 4),
                              ),
                            ],
                          ),
                          child: Hero(
                            tag: 'mix_cover_${mix.id}',
                            child: AutogeneratedMixCover(
                              mix: mix,
                              size: 210,
                              borderRadius: 32,
                              styleOverride: widget.styleOverride,
                              showBadge: true,
                            ),
                          ),
                        ),
                      );
                    },
                  ),
                ),

                const SizedBox(height: 24),

                // Title & Subtitle Card
                Center(
                  child: Column(
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                        decoration: BoxDecoration(
                          color: mix.primaryColor.withValues(alpha: 0.20),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(
                            color: mix.primaryColor.withValues(alpha: 0.45),
                            width: 1.0,
                          ),
                        ),
                        child: Text(
                          mix.badge,
                          style: AttuneTypography.soraBadge(
                            color: mix.primaryColor,
                            fontWeight: FontWeight.w700,
                            fontSize: 11,
                          ),
                        ),
                      ),
                      const SizedBox(height: 10),
                      Text(
                        mix.title,
                        style: AttuneTypography.soraHeading(
                          fontSize: 26,
                          fontWeight: FontWeight.w800,
                          color: Colors.white,
                        ),
                        textAlign: TextAlign.center,
                      ),
                      const SizedBox(height: 6),
                      Text(
                        mix.subtitle,
                        style: AttuneTypography.jakartaBodySmall(
                          fontSize: 13,
                          color: Colors.white70,
                        ),
                        textAlign: TextAlign.center,
                      ),
                      const SizedBox(height: 12),
                      Wrap(
                        alignment: WrapAlignment.center,
                        spacing: 8,
                        runSpacing: 6,
                        children: [
                          _buildMetaChip('${mix.tracks.length} Tracks', colorScheme),
                          _buildMetaChip(totalRuntime, colorScheme),
                          _buildMetaChip(bpmSpan, colorScheme),
                          _buildMetaChip(losslessRatio, colorScheme),
                        ],
                      ),
                    ],
                  ),
                ),

                const SizedBox(height: 20),

                // Google M3 Split Pill Button: [ ▶ Play Mix | ▾ ]
                Center(
                  child: _buildM3SplitPillButton(
                    colorScheme: colorScheme,
                    mix: mix,
                    onPlay: () {
                      ForYouService.instance.playMix(
                        mix,
                        onOpenNowPlaying: widget.onOpenNowPlaying,
                      );
                    },
                    onSelected: (action) {
                      if (action == 'shuffle' && mix.tracks.isNotEmpty) {
                        final shuffled = List<TrackItem>.from(mix.tracks)..shuffle();
                        controller.playTrack(shuffled.first);
                        for (int i = 1; i < shuffled.length; i++) {
                          controller.addToQueue(shuffled[i]);
                        }
                        widget.onOpenNowPlaying?.call();
                      } else if (action == 'queue_all') {
                        for (final t in mix.tracks) {
                          controller.addToQueue(t);
                        }
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text('Added ${mix.tracks.length} tracks to queue'),
                            duration: const Duration(seconds: 2),
                          ),
                        );
                      }
                    },
                  ),
                ),

                const SizedBox(height: 24),

                // "Why this playlist was chosen" Section
                LiquidGlassContainer(
                  borderRadius: 24,
                  surfaceAlpha: 0.92,
                  tintOverride: const Color(0xF2141923),
                  borderColor: mix.primaryColor.withValues(alpha: 0.35),
                  padding: const EdgeInsets.all(18),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.6),
                      blurRadius: 20,
                      offset: const Offset(0, 6),
                    ),
                  ],
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Icon(Icons.auto_awesome_rounded, color: mix.primaryColor, size: 20),
                          const SizedBox(width: 8),
                          Text(
                            'WHY THIS PLAYLIST WAS CHOSEN',
                            style: AttuneTypography.soraBadge(
                              fontSize: 11,
                              color: mix.primaryColor,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 10),
                      Text(
                        _synthesizeMixRationale(mix),
                        style: AttuneTypography.jakartaBody(
                          color: Colors.white.withValues(alpha: 0.88),
                          fontSize: 13,
                          height: 1.5,
                        ),
                      ),
                    ],
                  ),
                ),

                const SizedBox(height: 24),

                // Mix Tracklist
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      'MIX TRACKLIST (${mix.tracks.length})',
                      style: AttuneTypography.soraSectionHeader(
                        color: colorScheme.primary,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    Text(
                      'Total: $totalRuntime',
                      style: AttuneTypography.jakartaBodySmall(
                        color: Colors.white54,
                        fontSize: 11.5,
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 12),

                LiquidGlassContainer(
                  borderRadius: 24,
                  surfaceAlpha: 0.90,
                  tintOverride: const Color(0xF2121721),
                  borderColor: Colors.white.withValues(alpha: 0.10),
                  padding: const EdgeInsets.symmetric(vertical: 8),
                  child: Column(
                    children: mix.tracks.asMap().entries.map((entry) {
                      final idx = entry.key;
                      final track = entry.value;
                      final isCurrent = controller.currentTrack?.id == track.id;

                      return Material(
                        color: isCurrent
                            ? colorScheme.primary.withValues(alpha: 0.15)
                            : Colors.transparent,
                        child: ListTile(
                          contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 2),
                          leading: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              SizedBox(
                                width: 24,
                                child: Text(
                                  '${idx + 1}',
                                  style: AttuneTypography.soraMetric(
                                    fontSize: 12,
                                    color: isCurrent
                                        ? colorScheme.primary
                                        : Colors.white38,
                                  ),
                                  textAlign: TextAlign.center,
                                ),
                              ),
                              const SizedBox(width: 8),
                              Container(
                                width: 44,
                                height: 44,
                                decoration: BoxDecoration(
                                  borderRadius: BorderRadius.circular(10),
                                  border: Border.all(
                                    color: isCurrent
                                        ? colorScheme.primary
                                        : Colors.white12,
                                    width: 1.0,
                                  ),
                                ),
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(9),
                                  child: track.artworkFile != null && File(track.artworkFile!).existsSync()
                                      ? Image.file(File(track.artworkFile!), fit: BoxFit.cover)
                                      : Container(
                                          color: track.seedColor.withValues(alpha: 0.3),
                                          child: Icon(
                                            Icons.music_note_rounded,
                                            size: 22,
                                            color: track.seedColor,
                                          ),
                                        ),
                                ),
                              ),
                            ],
                          ),
                          title: Text(
                            track.title,
                            style: AttuneTypography.jakartaBodyLarge(
                              color: isCurrent ? colorScheme.primary : Colors.white,
                              fontWeight: isCurrent ? FontWeight.w700 : FontWeight.w600,
                              fontSize: 14,
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                          subtitle: Row(
                            children: [
                              Expanded(
                                child: Text(
                                  track.artist.isNotEmpty ? track.artist : 'Unknown Artist',
                                  style: AttuneTypography.jakartaBodySmall(
                                    color: Colors.white60,
                                    fontSize: 12,
                                  ),
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                ),
                              ),
                              if (track.hasBpm)
                                Text(
                                  '${track.formattedBpm} BPM',
                                  style: TextStyle(
                                    fontSize: 10,
                                    color: colorScheme.primary.withValues(alpha: 0.75),
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                            ],
                          ),
                          trailing: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(
                                _formatDuration(track.duration),
                                style: AttuneTypography.jakartaBodySmall(
                                  color: Colors.white38,
                                  fontSize: 11,
                                ),
                              ),
                              const SizedBox(width: 8),
                              IconButton(
                                icon: Icon(
                                  isCurrent && controller.isPlaying
                                      ? Icons.pause_circle_filled_rounded
                                      : Icons.play_circle_fill_rounded,
                                  color: isCurrent
                                      ? colorScheme.primary
                                      : Colors.white38,
                                  size: 24,
                                ),
                                onPressed: () {
                                  if (isCurrent) {
                                    controller.togglePlay();
                                  } else {
                                    controller.playTrack(track);
                                    widget.onOpenNowPlaying?.call();
                                  }
                                },
                              ),
                            ],
                          ),
                        ),
                      );
                    }).toList(),
                  ),
                ),

                const SizedBox(height: 90),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _buildMetaChip(String label, ColorScheme colorScheme) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.08),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: Colors.white12),
      ),
      child: Text(
        label,
        style: AttuneTypography.soraBadge(fontSize: 11, color: Colors.white70),
      ),
    );
  }

  Widget _buildM3SplitPillButton({
    required ColorScheme colorScheme,
    required ForYouMix mix,
    required VoidCallback onPlay,
    required void Function(String) onSelected,
  }) {
    return Container(
      height: 48,
      decoration: BoxDecoration(
        color: mix.primaryColor,
        borderRadius: BorderRadius.circular(24),
        boxShadow: [
          BoxShadow(
            color: mix.primaryColor.withValues(alpha: 0.40),
            blurRadius: 16,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Material(
            color: Colors.transparent,
            child: InkWell(
              borderRadius: const BorderRadius.only(
                topLeft: Radius.circular(24),
                bottomLeft: Radius.circular(24),
              ),
              onTap: onPlay,
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.play_arrow_rounded, color: Colors.white, size: 22),
                    const SizedBox(width: 8),
                    Text(
                      'Play Mix',
                      style: AttuneTypography.soraHeading(
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
          Container(
            width: 1,
            height: 24,
            color: Colors.white.withValues(alpha: 0.25),
          ),
          PopupMenuButton<String>(
            tooltip: 'Mix Options',
            borderRadius: BorderRadius.circular(16),
            color: const Color(0xFF1E232A),
            elevation: 8,
            icon: const Icon(Icons.arrow_drop_down_rounded, color: Colors.white, size: 24),
            onSelected: onSelected,
            itemBuilder: (context) => [
              const PopupMenuItem(
                value: 'shuffle',
                child: Row(
                  children: [
                    Icon(Icons.shuffle_rounded, size: 18, color: Colors.white70),
                    SizedBox(width: 10),
                    Text('Shuffle Mix', style: TextStyle(color: Colors.white)),
                  ],
                ),
              ),
              const PopupMenuItem(
                value: 'queue_all',
                child: Row(
                  children: [
                    Icon(Icons.queue_music_rounded, size: 18, color: Colors.white70),
                    SizedBox(width: 10),
                    Text('Add All to Queue', style: TextStyle(color: Colors.white)),
                  ],
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}
